from html.parser import HTMLParser
from urllib.request import build_opener, ProxyHandler, HTTPRedirectHandler
from urllib.parse import urljoin

class NoRedirect(HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None

class Page(HTMLParser):
    def __init__(self):
        super().__init__()
        self.href = None
        self.links = {}
        self.heading = \"\"
        self.in_heading = False
        self.lang = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == \"html\":
            self.lang = attrs.get(\"lang\")
        if tag == \"a\":
            self.href = attrs.get(\"href\")
            self.label = \"\"
        if tag == \"h1\":
            self.in_heading = True

    def handle_data(self, data):
        if self.href is not None:
            self.label += data
        if self.in_heading:
            self.heading += data

    def handle_endtag(self, tag):
        if tag == \"a\" and self.href is not None:
            self.links[self.label.strip()] = self.href
            self.href = None
        if tag == \"h1\":
            self.in_heading = False

origin = \"http://127.0.0.1:41639\"
opener = build_opener(ProxyHandler({}), NoRedirect())

def read(path):
    assert path.startswith(\"/\") and not path.startswith(\"//\")
    with opener.open(urljoin(origin, path), timeout=5) as response:
        page = Page()
        page.feed(response.read().decode())
        print(response.status, path, page.lang, page.heading)
        return page

